vector<int> parse_csv_ints(const string& s) {
    vector<int> result;
    stringstream ss(s);
    string segment;

    while (getline(ss, segment, ',')) {
        // Trim leading whitespace
        size_t start = segment.find_first_not_of(" \t\r\n");
        if (start == string::npos) {
            // Empty or whitespace-only segment, skip
            continue;
        }
        // Trim trailing whitespace
        size_t end = segment.find_last_not_of(" \t\r\n");
        string trimmed = segment.substr(start, end - start + 1);

        // Try to parse as integer
        try {
            size_t pos;
            int val = stoi(trimmed, &pos);
            // Ensure the entire trimmed string was consumed (no extra characters)
            if (pos == trimmed.size()) {
                result.push_back(val);
            }
        } catch (...) {
            // Not a valid integer, skip
            continue;
        }
    }

    return result;
}
