def eval_expr(expr: str) -> int:
    """
    Evaluate an integer arithmetic expression with +, -, *, /, parentheses.
    Division truncates toward zero.
    """
    # Remove spaces
    expr = expr.replace(' ', '')

    pos = 0
    n = len(expr)

    def parse_expression():
        """Parse addition and subtraction (lowest precedence)."""
        nonlocal pos
        result = parse_term()
        while pos < n and expr[pos] in '+-':
            op = expr[pos]
            pos += 1
            term = parse_term()
            if op == '+':
                result += term
            else:
                result -= term
        return result

    def parse_term():
        """Parse multiplication and division (higher precedence)."""
        nonlocal pos
        result = parse_factor()
        while pos < n and expr[pos] in '*/':
            op = expr[pos]
            pos += 1
            factor = parse_factor()
            if op == '*':
                result *= factor
            else:
                # Truncate toward zero
                if result * factor < 0:
                    result = -((-result) // factor) if result < 0 else -(result // (-factor))
                    # Simpler: use int() on float division or manual truncation
                    # Actually, let's use a cleaner approach
                    result = int(result / factor) if result * factor < 0 else result // factor
                    # But int() on float can have precision issues. Let's do it properly.
                    # Truncation toward zero:
                    if result < 0 and factor > 0:
                        result = -((-result) // factor)
                    elif result > 0 and factor < 0:
                        result = -(result // (-factor))
                    else:
                        result = result // factor
        return result

    def parse_factor():
        """Parse a number or parenthesized expression, handling unary minus."""
        nonlocal pos
        if pos < n and expr[pos] == '(':
            pos += 1  # skip '('
            result = parse_expression()
            if pos < n and expr[pos] == ')':
                pos += 1  # skip ')'
            return result
        elif pos < n and expr[pos] == '-':
            pos += 1  # skip '-'
            return -parse_factor()
        elif pos < n and expr[pos] == '+':
            pos += 1  # skip '+'
            return parse_factor()
        else:
            # Parse a number
            start = pos
            while pos < n and expr[pos].isdigit():
                pos += 1
            return int(expr[start:pos])

    return parse_expression()
